import timeit

class BadKey:
    """Every instance has the same hash: all keys collide."""
    def __init__(self, n): self.n = n
    def __hash__(self): return 1
    def __eq__(self, other): return self.n == other.n

class GoodKey(BadKey):
    def __hash__(self): return hash(self.n)

def fill(kind, size):
    return {kind(i): i for i in range(size)}

for kind in (GoodKey, BadKey):
    seconds = timeit.timeit(lambda: fill(kind, 1000), number=3)
    print(f"{kind.__name__}: {seconds:.3f}s for 3 x 1000 inserts")

