class OutOfStock(Exception):
    def __init__(self, sku: str, wanted: int, available: int):
        super().__init__(f"{sku}: wanted {wanted}, only {available} left")
        self.sku, self.available = sku, available

STOCK = {"milk": 3}

def reserve(sku: str, qty: int) -> None:
    available = STOCK.get(sku, 0)
    if qty > available:
        raise OutOfStock(sku, qty, available)
    STOCK[sku] = available - qty

try:
    reserve("milk", 2)
    reserve("milk", 5)
except OutOfStock as err:
    print("tell the user:", err, "| can offer", err.available)
except Exception as err:          # last resort, log and re-raise
    print("unexpected", err)
    raise
else:
    print("all reserved")
finally:
    print("stock now", STOCK)

