from abc import ABC, abstractmethod

class PaymentMethod(ABC):
    fee_percent = 0.0                         # class attribute: shared default

    def __init__(self, owner: str):
        self.owner = owner

    @abstractmethod
    def charge(self, paise: int) -> str: ...

    def total(self, paise: int) -> int:       # shared behaviour
        return round(paise * (1 + self.fee_percent / 100))

class Card(PaymentMethod):
    fee_percent = 1.8
    def charge(self, paise: int) -> str:
        return f"card: {self.owner} pays {self.total(paise)}"

class Upi(PaymentMethod):
    def charge(self, paise: int) -> str:
        return f"upi: {self.owner} pays {self.total(paise)}"

class Audited:
    def charge(self, paise: int) -> str:
        return "[logged] " + super().charge(paise)     # next class in the MRO

class AuditedCard(Audited, Card):
    pass

