PaymentResult = Paid | Declined

def describe(result: PaymentResult) -> str:
    match result:
        case Paid(reference=reference):
            return f"paid, ref {reference}"
        case Declined(reason=reason):
            return f"declined: {reason}"
        case _:
            assert_never(result)         # adding a third class makes this a type error

