import functools, time

def log(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"  log: calling {func.__name__}{args}")
        result = func(*args, **kwargs)
        print(f"  log: {func.__name__} returned {result}")
        return result
    return wrapper

def require_role(role):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(user, *args, **kwargs):
            if role not in user["roles"]:
                raise PermissionError(f"{user['name']} needs role {role}")
            return func(user, *args, **kwargs)
        return wrapper
    return decorator

@log                      # outermost: runs first, sees the PermissionError too
@require_role("support")  # innermost: applied first
def refund(user, order_id):
    return f"refunded {order_id}"

print(refund({"name": "Asha", "roles": ["support"]}, 184))
try:
    refund({"name": "Ravi", "roles": []}, 185)
except PermissionError as err:
    print("denied:", err)

class RateLimit:                               # a decorator with state
    def __init__(self, calls: int, per_seconds: float):
        self.calls, self.per, self.stamps = calls, per_seconds, []
    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()
            self.stamps = [t for t in self.stamps if now - t < self.per]
            if len(self.stamps) >= self.calls:
                raise RuntimeError("rate limit exceeded")
            self.stamps.append(now)
            return func(*args, **kwargs)
        return wrapper

@RateLimit(calls=2, per_seconds=1)
def send_otp(phone): return f"otp sent to {phone}"

for attempt in range(3):
    try: print(send_otp("98xxxx"))
    except RuntimeError as err: print("blocked:", err)

