import hashlib, hmac, os, time
import jwt     # pip install pyjwt

SECRET = os.getenv("JWT_SECRET", "local-demo-only-load-the-real-one-from-env")

def hash_password(password: str) -> str:
    salt = os.urandom(16)                                   # different for every user
    digest = hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)
    return salt.hex() + ":" + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    salt_hex, digest_hex = stored.split(":")
    digest = hashlib.scrypt(password.encode(), salt=bytes.fromhex(salt_hex), n=2**14, r=8, p=1)
    return hmac.compare_digest(digest.hex(), digest_hex)    # constant-time compare

def make_token(user_id: int, minutes: int = 15) -> str:
    now = int(time.time())
    return jwt.encode({"sub": str(user_id), "iat": now, "exp": now + minutes * 60}, SECRET, algorithm="HS256")

def read_token(token: str) -> int:
    return int(jwt.decode(token, SECRET, algorithms=["HS256"])["sub"])

stored = hash_password("correct horse")
print(verify_password("correct horse", stored), verify_password("wrong", stored))
token = make_token(7)
print("user", read_token(token), "| token parts:", len(token.split(".")))
for bad in (make_token(7, minutes=-1), token[:-2] + "xx"):
    try:
        read_token(bad)
    except jwt.ExpiredSignatureError:
        print("rejected: expired -> 401, client should refresh")
    except jwt.InvalidTokenError:
        print("rejected: tampered -> 401")

import secrets, time
from dataclasses import dataclass, field

@dataclass
class TokenStore:
    """Refresh-token rotation with reuse detection. Production: a database table."""
    active: dict[str, tuple[int, str]] = field(default_factory=dict)    # token -> (user_id, family)
    used: dict[str, str] = field(default_factory=dict)                   # spent token -> family
    revoked_families: set[str] = field(default_factory=set)

    def issue(self, user_id: int, family: str | None = None) -> str:
        token = secrets.token_urlsafe(16)
        self.active[token] = (user_id, family or secrets.token_hex(4))
        return token

    def rotate(self, token: str) -> str:
        if token in self.used:                              # an old token came back: theft
            self.revoked_families.add(self.used[token])
            self.active = {t: v for t, v in self.active.items() if v[1] not in self.revoked_families}
            raise PermissionError("refresh token reuse detected: all sessions revoked")
        if token not in self.active:
            raise PermissionError("unknown refresh token")
        user_id, family = self.active.pop(token)
        self.used[token] = family
        return self.issue(user_id, family)

