class TokenBucket:                            # rate limiting: steady refill, small bursts allowed
    def __init__(self, rate_per_second: float, burst: int):
        self.rate, self.capacity, self.tokens, self.stamp = rate_per_second, burst, float(burst), time.monotonic()
    def allow(self) -> bool:
        now = time.monotonic()
        self.tokens = min(self.capacity, self.tokens + (now - self.stamp) * self.rate)
        self.stamp = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
bucket = TokenBucket(rate_per_second=1, burst=3)
print([bucket.allow() for _ in range(5)])     # three pass, then 429

