from fastapi import FastAPI, WebSocket, WebSocketDisconnect

app = FastAPI()
riders: dict[int, set[WebSocket]] = {}

@app.websocket("/ws/orders/{order_id}")
async def track(websocket: WebSocket, order_id: int) -> None:
    await websocket.accept()
    riders.setdefault(order_id, set()).add(websocket)
    try:
        while True:
            location = await websocket.receive_json()          # rider app sends lat/lon
            for peer in riders[order_id]:
                await peer.send_json({"order_id": order_id, **location})
    except WebSocketDisconnect:
        riders[order_id].discard(websocket)

