import math, re
from collections import Counter

def chunk(text: str, size: int = 12, overlap: int = 4) -> list[str]:
    """Sliding window over words. Real systems split on headings and paragraphs first."""
    words = text.split()
    return [" ".join(words[i:i + size]) for i in range(0, max(1, len(words) - overlap), size - overlap)]

print(chunk("Refunds for damaged items go to the original payment method within five days of the request being approved.", 8, 3))

CHUNKS = [
    "Fresh milk can be returned at the door if the seal is broken.",
    "Delivery is free above 500 rupees and costs 40 rupees below that.",
    "Refunds for damaged items go to the original payment method within five days.",
    "Coupon SAVE50 gives 50 rupees off the first order.",
    "Coupon FRESH20 gives 20 percent off fruit and vegetables.",
]
STOP = {"is", "the", "a", "do", "i", "my", "how", "what", "get", "for", "at", "if", "and", "of", "to", "does"}
words = lambda text: [w for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in STOP]
doc_words = [words(c) for c in CHUNKS]
doc_freq = Counter(w for doc in doc_words for w in set(doc))

def keyword_rank(query: str) -> list[int]:
    """Exact-word matching (a tiny TF-IDF standing in for BM25). Returns only chunks that match."""
    scores = {}
    for i, doc in enumerate(doc_words):
        counts = Counter(doc)
        score = sum(counts[w] * math.log(1 + len(CHUNKS) / doc_freq[w]) for w in words(query) if w in counts)
        if score:
            scores[i] = score
    return sorted(scores, key=lambda i: -scores[i])

CONCEPT = {"refunds": "refund", "money": "refund", "back": "refund", "returned": "return", "delivery": "delivery",
           "shipping": "delivery", "free": "free", "coupon": "discount", "off": "discount"}
concepts = lambda text: {CONCEPT[w] for w in words(text) if w in CONCEPT}

def vector_rank(query: str) -> list[int]:
    """Meaning matching, simulated with a concept table. A real system compares embedding vectors."""
    overlap = {i: len(concepts(query) & concepts(c)) for i, c in enumerate(CHUNKS)}
    return sorted((i for i in overlap if overlap[i]), key=lambda i: -overlap[i])

def hybrid_rank(query: str, k: int = 60) -> list[int]:
    fused = Counter()                                   # reciprocal rank fusion
    for ranking in (keyword_rank(query), vector_rank(query)):
        for position, doc_id in enumerate(ranking):
            fused[doc_id] += 1 / (k + position + 1)
    return [doc_id for doc_id, _ in fused.most_common()]

EVAL = [("how do I get my money back", "refunds"), ("is shipping free", "delivery is free"), ("what does coupon FRESH20 give", "fresh20")]

def recall_at(k: int, ranker) -> float:
    hits = sum(any(needle in CHUNKS[i].lower() for i in ranker(question)[:k]) for question, needle in EVAL)
    return hits / len(EVAL)

for name, ranker in (("keyword", keyword_rank), ("vector ", vector_rank), ("hybrid ", hybrid_rank)):
    print(f"{name}: recall@1 = {recall_at(1, ranker):.2f}   top hit per question: {[ranker(q)[:1] for q, _ in EVAL]}")

from dataclasses import dataclass
from typing import Callable

@dataclass
class Case:
    question: str
    must_contain: list[str]
    must_not_contain: list[str]

CASES = [
    Case("Is delivery free above 500?", ["free"], ["40"]),
    Case("What is the delivery fee for a 200 rupee order?", ["40"], ["free"]),
    Case("Can I pay with cryptocurrency?", ["do not know"], ["yes"]),
]

def fake_assistant(question: str) -> str:
    """Stands in for the real model call so this file runs anywhere."""
    if "500" in question:
        return "Yes, delivery is free above 500 rupees."
    if "200" in question:
        return "The fee is 40 rupees."
    return "Yes, you can."                       # a wrong, made-up answer

def grade(case: Case, answer: str) -> bool:
    text = answer.lower()
    return all(w in text for w in case.must_contain) and not any(w in text for w in case.must_not_contain)

def run_eval(assistant: Callable[[str], str]) -> float:
    passed = 0
    for case in CASES:
        answer = assistant(case.question)
        ok = grade(case, answer)
        passed += ok
        print("PASS" if ok else "FAIL", "|", case.question, "->", answer)
    return passed / len(CASES)

print(f"score: {run_eval(fake_assistant):.0%}")

from dataclasses import dataclass

@dataclass
class Example:
    text: str
    is_complaint: bool

DATA = [
    Example("My order arrived two hours late", True), Example("The milk was spoiled", True),
    Example("Half my items are missing!", True), Example("Great service, thanks", False),
    Example("Where can I change my address?", False), Example("Do you deliver on Sunday?", False),
    Example("The delivery partner was late but polite", True), Example("Is the late night slot available?", False),
]

def classify_v1(text: str) -> bool:                    # stands in for a prompt + model
    return any(word in text.lower() for word in ("late", "spoiled"))

def classify_v2(text: str) -> bool:
    lowered = text.lower()
    return any(w in lowered for w in ("spoiled", "missing", "arrived two hours late", "was late"))

def score(classifier) -> dict[str, float]:
    tp = sum(classifier(e.text) and e.is_complaint for e in DATA)
    fp = sum(classifier(e.text) and not e.is_complaint for e in DATA)
    fn = sum(not classifier(e.text) and e.is_complaint for e in DATA)
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {"precision": round(precision, 2), "recall": round(recall, 2), "f1": round(f1, 2)}

baseline, candidate = score(classify_v1), score(classify_v2)
print("v1 (in production):", baseline)
print("v2 (candidate):    ", candidate)

def gate(baseline: dict, candidate: dict, tolerance: float = 0.02) -> bool:
    worse = [name for name in baseline if candidate[name] < baseline[name] - tolerance]
    print("GATE:", "FAIL, regressed on " + ", ".join(worse) if worse else "PASS")
    return not worse

gate(baseline, candidate)

