type OrderStatus = "placed" | "packed" | "shipped" | "delivered";

interface OrderItem {
  sku: string;
  price: number;      // paise
  qty: number;
}

interface Order {
  id: number;
  status: OrderStatus;
  items: OrderItem[];
  coupon?: string;    // optional: string | undefined
}

function total(order: Order): number {
  return order.items.reduce((sum, i) => sum + i.price * i.qty, 0);
}

// A tagged union: every case carries different data.
type PaymentResult =
  | { kind: "paid"; transactionId: string }
  | { kind: "declined"; reason: string }
  | { kind: "pending"; retryAfterSeconds: number };

function describe(result: PaymentResult): string {
  switch (result.kind) {
    case "paid": return `Paid, ref ${result.transactionId}`;
    case "declined": return `Declined: ${result.reason}`;
    case "pending": return `Retry in ${result.retryAfterSeconds}s`;
  }                    // adding a fourth kind makes this a compile error until handled
}

// Generics: one function, many types, still checked.
async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return (await response.json()) as T;   // a promise about the shape, not a check
}

