// A result type instead of exceptions, narrowed by a literal field.
type ApiResult<T> = { ok: true; data: T } | { ok: false; error: string };
function describe(result: ApiResult<Order>): string {
  if (!result.ok) return `failed: ${result.error}`;  // here: the error shape
  return `order ${result.data.id}`;                  // here: the success shape
}

// A type guard for data of unknown origin.
function isOrder(value: unknown): value is Order {
  return typeof value === "object" && value !== null
    && "id" in value && typeof (value as { id: unknown }).id === "number";
}

