async function retry(fn, { attempts = 4, baseMs = 10 } = {}) {
  for (let attempt = 1; ; attempt++) {
    try { return await fn(attempt); }
    catch (err) {
      if (attempt === attempts || !err.retryable) throw err;
      const delay = Math.random() * baseMs * 2 ** (attempt - 1);     // exponential backoff with full jitter
      console.log(`attempt ${attempt} failed (${err.message}), retrying`);
      await sleep(delay);
    }
  }
}
