function slowDisk(log) {
  return new Writable({
    objectMode: true,
    highWaterMark: 4,                                    // buffer at most 4 rows
    write(row, _encoding, done) { log.maxBuffered = Math.max(log.maxBuffered, this.writableLength); setTimeout(done, 2); },
  });
}

const careless = { maxBuffered: 0 };                    // ignores the return value of write()
const sink1 = slowDisk(careless);
for (let id = 1; id <= 200; id++) sink1.write({ id });
sink1.end();
await once(sink1, "finish");

const careful = { maxBuffered: 0, waits: 0 };           // respects backpressure
const sink2 = slowDisk(careful);
for (let id = 1; id <= 200; id++) {
  if (!sink2.write({ id })) { careful.waits++; await once(sink2, "drain"); }
}
sink2.end();
await once(sink2, "finish");
console.log("ignoring backpressure: up to", careless.maxBuffered, "rows held in memory");
console.log("respecting it:         up to", careful.maxBuffered, "rows, paused", careful.waits, "times");

