  #next = 1;
  constructor(total) { super({ objectMode: true, highWaterMark: 2 }); this.total = total; }
  _read() {                                             // called only when the consumer wants more
    this.push(this.#next <= this.total ? { id: this.#next++ } : null);     // null ends the stream
  }
}
