function createApp() {
  const stack = [];
  return {
    use(fn) { stack.push(fn); return this; },
    async handle(req, res) {
      let index = 0;
      const next = async (err) => {
        while (index < stack.length) {
          const fn = stack[index++];
          const handlesErrors = fn.length === 4;           // (err, req, res, next)
          if (Boolean(err) !== handlesErrors) continue;     // skip the wrong kind
          try {
            return await (err ? fn(err, req, res, next) : fn(req, res, next));
          } catch (thrown) {
            return next(thrown);                            // a throw becomes next(err)
          }
        }
        if (err) { res.status = 500; res.body = { error: "unhandled" }; }
      };
      await next();
      return res;
    },
  };
}

const app = createApp()
  .use(async (req, res, next) => {                          // timing: wraps everything after it
    const start = performance.now();
    await next();
