export async function placeOrder(userId, items) {
  const client = await pool.connect();  // one connection for the whole transaction
  try {
    await client.query("BEGIN");
    const { rows: [order] } = await client.query(
      "INSERT INTO orders (user_id, status) VALUES ($1, 'placed') RETURNING id",
      [userId],
    );
    for (const item of items) {
      const stock = await client.query(
        "UPDATE stock SET available = available - $2 WHERE sku = $1 AND available >= $2",
        [item.sku, item.qty],
      );
      if (stock.rowCount === 0) throw new Error(`out of stock: ${item.sku}`);
      await client.query(
        "INSERT INTO order_items (order_id, sku, qty) VALUES ($1, $2, $3)",
        [order.id, item.sku, item.qty],
      );
    }
    await client.query("COMMIT");
    return order.id;
  } catch (err) {
    await client.query("ROLLBACK");     // nothing from this order is saved
    throw err;
  } finally {
    client.release();                   // always give the connection back
  }
}

