function createPool(size) {                         // the essential behaviour of pg.Pool
  let free = size;
  const waiters = [];
  return {
    async connect() {
      if (free > 0) free--;
      else await new Promise((resolve) => waiters.push(resolve));
      let released = false;
      return { release() { if (released) return; released = true; const next = waiters.shift(); next ? next() : free++; } };
    },
    stats: () => ({ free, waiting: waiters.length }),
  };
}

async function leakyHandler(pool, fail) {
  const client = await pool.connect();
  await sleep(5);
  if (fail) throw new Error("validation failed");   // returns without releasing: a leaked connection
  client.release();
}
async function safeHandler(pool, fail) {
  const client = await pool.connect();
  try {
    await sleep(5);
    if (fail) throw new Error("validation failed");
  } finally {
    client.release();                               // runs on success and on error
  }
}

for (const [name, handler] of [["leaky", leakyHandler], ["safe ", safeHandler]]) {
  const pool = createPool(3);
  await Promise.allSettled([1, 2, 3].map(() => handler(pool, true)));        // three failing requests
  const next = handler(pool, false).then(() => "served");
  const outcome = await Promise.race([next, sleep(100, "HUNG: no free connection")]);
  console.log(name, "handler ->", outcome, pool.stats());
}

