function requireAuth(req, res, next) {
  const [scheme, token] = (req.headers.authorization ?? "").split(" ");
  if (scheme !== "Bearer" || !token) return res.status(401).json({ error: "missing_token" });
  try {
    const claims = jwt.verify(token, SECRET, { algorithms: ["HS256"] });   // always pin the algorithm
    req.userId = Number(claims.sub);
    next();
  } catch (err) {
    res.status(401).json({ error: err instanceof jwt.TokenExpiredError ? "token_expired" : "invalid_token" });
  }
}

