import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";

const SECRET = process.env.SESSION_SECRET ?? "local-demo-only";
const sessions = new Map();                                // production: Redis with an expiry

const mac = (value) => createHmac("sha256", SECRET).update(value).digest("base64url");
const sign = (value) => `${value}.${mac(value)}`;
function unsign(signed) {
  const dot = signed.lastIndexOf(".");
  if (dot < 0) return null;
  const value = signed.slice(0, dot);
  const given = Buffer.from(signed.slice(dot + 1));
  const expected = Buffer.from(mac(value));
  return given.length === expected.length && timingSafeEqual(given, expected) ? value : null;
}

function login(userId, roles) {
  const id = randomBytes(16).toString("hex");
  const csrfToken = randomBytes(16).toString("hex");
  sessions.set(id, { userId, roles, csrfToken });
  return { setCookie: `sid=${sign(id)}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=1209600`, csrfToken };
}

function authenticate(req) {
  const cookies = Object.fromEntries((req.headers.cookie ?? "").split("; ").filter(Boolean).map((c) => c.split(/=(.*)/s).slice(0, 2)));
  const id = cookies.sid && unsign(cookies.sid);
  return id ? sessions.get(id) ?? null : null;
}

const requireRole = (role) => (req) => {
  const session = authenticate(req);
  if (!session) return 401;
  if (req.method !== "GET" && req.headers["x-csrf-token"] !== session.csrfToken) return 403;   // CSRF check on writes
  return session.roles.includes(role) ? 200 : 403;
};

