function backoffDelays({ baseMs = 500, maxMs = 30_000, attempts = 8, random = Math.random } = {}) {
  return Array.from({ length: attempts }, (_, attempt) => {
    const ceiling = Math.min(maxMs, baseMs * 2 ** attempt);
    return Math.round(random() * ceiling);                 // "full jitter": anywhere from 0 to the ceiling
  });
}
