function createQueue({ concurrency, attempts, handler }) {       // what BullMQ gives you, minus persistence
  const pending = [];
  let running = 0;
  let idle;
  const done = new Promise((resolve) => (idle = resolve));
  const pump = () => {
    while (running < concurrency && pending.length) {
      const job = pending.shift();
      running++;
      handler(job.data)
        .then(() => console.log("done  ", job.data.orderId))
        .catch((err) => {
          if (++job.tries < attempts) { console.log("retry ", job.data.orderId, `(${err.message})`); pending.push(job); }
          else console.log("failed", job.data.orderId, "-> dead-letter queue");
        })
        .finally(() => { running--; pump(); if (!running && !pending.length) idle(); });
    }
  };
  return { add: (data) => { pending.push({ data, tries: 0 }); pump(); }, done };
}

