import { Worker } from "node:worker_threads";
import { availableParallelism } from "node:os";

const TASK = `
  const { parentPort } = require("node:worker_threads");
  parentPort.on("message", ({ from, to }) => {
    let primes = 0;
    for (let n = Math.max(2, from); n < to; n++) {
      let isPrime = true;
      for (let d = 2; d * d <= n; d++) if (n % d === 0) { isPrime = false; break; }
      if (isPrime) primes++;
    }
    parentPort.postMessage(primes);
  });
`;

class WorkerPool {
  #idle = []; #queue = []; #workers = [];
  constructor(size) {
    for (let i = 0; i < size; i++) {
      const worker = new Worker(TASK, { eval: true });
      worker.on("message", (result) => { worker.job.resolve(result); this.#idle.push(worker); this.#next(); });
      worker.on("error", (err) => worker.job?.reject(err));
      this.#workers.push(worker);
      this.#idle.push(worker);
    }
  }
  run(data) {
    return new Promise((resolve, reject) => { this.#queue.push({ data, resolve, reject }); this.#next(); });
  }
  #next() {
    if (!this.#idle.length || !this.#queue.length) return;
    const worker = this.#idle.pop();
    worker.job = this.#queue.shift();
    worker.postMessage(worker.job.data);
  }
  close() { return Promise.all(this.#workers.map((w) => w.terminate())); }
}

