  const pool = new WorkerPool(size);
  const start = Date.now();
  const counts = await Promise.all(ranges.map((range) => pool.run(range)));
  console.log(`${size} worker(s): ${counts.reduce((a, b) => a + b)} primes in ${Date.now() - start} ms`);
  await pool.close();
}

