    const final = await stream.finalMessage();
    res.write(`event: done\ndata: ${JSON.stringify({ outputTokens: final.usage.output_tokens })}\n\n`);
  } catch (err) {
    res.write(`event: error\ndata: ${JSON.stringify({ message: "assistant unavailable" })}\n\n`);
  } finally {
    res.end();
  }
});

