const tools = [{
  name: "get_order_status",
  description: "Look up the delivery status of one order by its numeric id.",
  input_schema: {
    type: "object",
    properties: { order_id: { type: "integer", description: "The order id, for example 184" } },
    required: ["order_id"],
    additionalProperties: false,
  },
  strict: true,
}];

async function executeTool(name, input, user) {
  if (name === "get_order_status") {
    const order = ORDERS[input.order_id];                 // production: also check the order belongs to user
    return order ? { content: JSON.stringify(order) } : { content: "no such order", is_error: true };
  }
  return { content: `unknown tool ${name}`, is_error: true };
}

const messages = [{ role: "user", content: "Where is order 184?" }];
