for (let turn = 0; turn < 8; turn++) {                    // a hard cap on iterations
  response = await client.messages.create({ model: "claude-opus-5-5", max_tokens: 16000, tools, messages });
  messages.push({ role: "assistant", content: response.content });       // the whole content array
  if (response.stop_reason !== "tool_use") break;

  const toolUses = response.content.filter((block) => block.type === "tool_use");
  const results = await Promise.all(toolUses.map(async (block) => ({     // run in parallel
    type: "tool_result",
    tool_use_id: block.id,
    ...(await executeTool(block.name, block.input, { id: 7 })),
  })));
  messages.push({ role: "user", content: results });                     // all results in one message
}
